  Button copy=button("复制已保存的非敏感配置","aiExport");copy.setOnClickListener(v->{if(!usable())return;try{android.content.ClipboardManager clipboard=(android.content.ClipboardManager)getContext().getSystemService(Context.CLIPBOARD_SERVICE);clipboard.setPrimaryClip(android.content.ClipData.newPlainText("非敏感 AI 配置",new String(exportArchive(),StandardCharsets.UTF_8)));message.setText("已复制已保存的非敏感配置；草稿未导出");}catch(Exception e){fail();}});
