 private boolean usable(){return active&&!closed;}
 private void notifyHost(){if(host!=null)try{host.configurationSaved(savedConfig());}catch(Exception e){message.setText("非敏感配置已保存；主页面通知失败。接口未验证。");}}
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private void label(String text){TextView v=new TextView(getContext());v.setText(text);body.addView(v,new LayoutParams(-1,-2));}
 private EditText edit(String title,String tag,int max){label(title);EditText e=new EditText(getContext());e.setTag(tag);e.setSaveEnabled(false);e.setSingleLine(true);e.setFilters(new InputFilter[]{new InputFilter.LengthFilter(max)});body.addView(e,new LayoutParams(-1,-2));e.setMinHeight(dp(48));return e;}
 private Button button(String text,String tag){Button b=new Button(getContext());b.setText(text);b.setTag(tag);body.addView(b,new LayoutParams(-1,dp(48)));return b;}
 private void paintText(View v){if(v instanceof TextView)((TextView)v).setTextColor(dark?Color.rgb(235,241,249):Color.rgb(25,41,62));}
 private void fail(){message.setText("操作失败：格式、范围或本地档案检查未通过。原输入未保存。");}
 private void invalidatePreview(){preview=null;apply.setEnabled(false);}
 private JSONObject draft()throws Exception{JSONObject p=new JSONObject().put("provider",new String[]{"manual-handoff","openai","openai-compatible"}[provider.getSelectedItemPosition()]).put("model",model.getText().toString()).put("endpoint",endpoint.getText().toString()).put("timeoutMs",Integer.parseInt(timeout.getText().toString())).put("maxCompletionTokens",Integer.parseInt(tokens.getText().toString())).put("temperature",temperature.getText().toString().isEmpty()?JSONObject.NULL:Double.parseDouble(temperature.getText().toString())).put("sendTemperature",sendTemperature.isChecked()).put("enabledPreference",enabled.isChecked());return AiSettingsModel.preferences(p);}
 private void fill(JSONObject p)throws Exception{filling=true;try{String[] opts={"manual-handoff","openai","openai-compatible"};for(int n=0;n<opts.length;n++)if(opts[n].equals(p.getString("provider")))provider.setSelection(n);model.setText(p.getString("model"));endpoint.setText(p.getString("endpoint"));timeout.setText(Integer.toString(p.getInt("timeoutMs")));tokens.setText(Integer.toString(p.getInt("maxCompletionTokens")));temperature.setText(p.isNull("temperature")?"":p.get("temperature").toString());sendTemperature.setChecked(p.getBoolean("sendTemperature"));enabled.setChecked(p.getBoolean("enabledPreference"));}finally{filling=false;}}
 private void refresh()throws Exception{JSONObject p=savedConfig();StringBuilder text=new StringBuilder("已保存配置：").append(p.getString("provider").equals("manual-handoff")?"手动交接模式":(AiSettingsModel.status(p).getString("configuration").equals("configured")?"字段完整":"字段未完整")).append("\n密钥存储与执行接口：尚未连接\n网络授权：未授权；连通检查：未测试\n本地保存与读回：").append(saved.isNull("savedAt")?"暂无记录":saved.getString("savedAt")).append("\n手动研究交接入口：").append(handoff.isEnabled()?"主页面已连接（登录及研究结果未验证）":"主页面尚未连接").append("\n\n模型能力声明\n来源：services/modelRegistryService.js；来源观察时间、运行验证时间：未知\n");JSONArray declarations=AiSettingsCapabilities.declarations();for(int n=0;n<declarations.length();n++)text.append(AiSettingsCapabilities.name(declarations.getJSONObject(n).getString("id"))).append("：代码声明，当前原生运行未验证\n");for(JSONArray group:new JSONArray[]{saved.getJSONArray("capabilities"),hostReports})for(int n=0;n<group.length();n++){JSONObject o=group.getJSONObject(n);text.append("\n").append(AiSettingsCapabilities.name(o.getString("id"))).append("：来源报告（未验证）\n来源：").append(o.getString("source")).append("；原声明：").append(o.getString("claimedStatus")).append("\n接收时间：").append(o.getString("importedAt")).append("；运行验证时间：未知\n");}evidence.setText(text.toString());}
 public JSONObject savedConfig(){try{return new JSONObject(saved.getJSONObject("preferences").toString());}catch(Exception e){return new JSONObject();}}
 public void importArchive(byte[] bytes){invalidatePreview();try{JSONObject safe=AiSettingsModel.parse(bytes);filling=true;try{importText.setText(safe.toString(2));}finally{filling=false;}safe.put("expectedRevision",saved.getLong("revision"));preview=safe;apply.setEnabled(true);evidence.setText(safe.toString(2));message.setText("预览只保留白名单配置；能力声明未验证。确认后覆盖保存配置。");}catch(Exception e){importText.setText("");fail();}}
 public byte[] exportArchive(){return saved.toString().getBytes(StandardCharsets.UTF_8);}
 public JSONObject saveState(){try{JSONObject safe=new JSONObject().put("schema","native-ai-settings-ui/v1").put("revision",saved.getLong("revision"));try{safe.put("draft",draft());}catch(Exception e){safe.put("draft",savedConfig());}if(preview!=null)safe.put("preview",preview);byte[] bytes=safe.toString().getBytes(StandardCharsets.UTF_8);AiSettingsModel.need(bytes.length<=256*1024,"安全草稿过大");FileOutputStream stream=uiFile.startWrite();try{stream.write(bytes);uiFile.finishWrite(stream);}catch(Exception e){uiFile.failWrite(stream);throw e;}return new JSONObject().put("schema","native-ai-settings-ui-marker/v1").put("digest",AiSettingsModel.hash(bytes));}catch(Exception e){fail();return new JSONObject();}}
 public void restoreState(JSONObject marker){try{if(!marker.optString("schema").equals("native-ai-settings-ui-marker/v1"))return;byte[] b=uiFile.readFully();AiSettingsModel.need(b.length<=256*1024&&AiSettingsModel.hash(b).equals(marker.optString("digest")),"安全草稿摘要无效");JSONObject s=new JSONObject(new String(b,StandardCharsets.UTF_8));if(s.optString("schema").equals("native-ai-settings-ui/v1")&&s.getLong("revision")==saved.getLong("revision")){fill(AiSettingsModel.preferences(s.getJSONObject("draft")));invalidatePreview();if(s.opt("preview") instanceof JSONObject)importArchive(s.getJSONObject("preview").toString().getBytes(StandardCharsets.UTF_8));}}catch(Exception e){fail();}}
 public void setHostCapabilities(JSONObject report){try{hostReports=AiSettingsCapabilities.reported(report.optJSONArray("capabilities"),"host");refresh();}catch(Exception e){fail();}}
 public void setHostError(String ignored){fail();}
