 public void setDarkTheme(boolean value){dark=value;setBackgroundColor(dark?Color.rgb(17,26,40):Color.rgb(245,248,252));int color=dark?Color.rgb(235,241,249):Color.rgb(25,41,62);ColorStateList tint=new ColorStateList(new int[][]{new int[]{-android.R.attr.state_enabled},new int[]{}},new int[]{dark?Color.rgb(126,145,165):Color.rgb(100,116,139),color});paintText(message);paintText(evidence);for(int n=0;n<body.getChildCount();n++){View v=body.getChildAt(n);paintText(v);if(v instanceof EditText)((EditText)v).setBackgroundTintList(tint);if(v instanceof Button){((Button)v).setTextColor(tint);v.setBackgroundTintList(ColorStateList.valueOf(dark?Color.rgb(39,55,77):Color.rgb(220,231,245)));}if(v instanceof CheckBox)((CheckBox)v).setButtonTintList(tint);}provider.setBackgroundTintList(tint);adapter.notifyDataSetChanged();}
